export const SIGN_ATTRIBUTION =
  "Traffic sign images are Crown copyright, reproduced from the Department for Transport under the Open Government Licence v3.0.";

export function signById(id: string): Sign | undefined {
  return SIGNS.find((s) => s.id === id);
}
